// FL.ru includes the budget and the «для всех» badge in some feed titles.
const topics = [
  { name: 'Telegram-боты', match: /(?:telegram|телеграм(?:м)?|тг|чат)[\s-]*(?:чат[\s-]*)?бот|бот.{0,20}(?:telegram|телеграм)|chatbot|aiogram/i },
  { name: 'Автоматизации', match: /n8n|автоматизац|автоматизир|webhook|вебхук|workflow automation/i },
  { name: 'Сайты', match: /лендинг|сайт|в[её]рстк|сверстать|landing page|website|wordpress|tilda|тильд/i },
  { name: 'Изображения и дизайн', match: /баннер|макет|обложк|иллюстрац|карточк.{0,12}товар|изображени|инфографик|ретуш|логотип|poster|illustration|banner|graphic design/i },
  { name: 'Видео', match: /видео|ролик|монтаж.{0,12}(?:reels|рилс)|субтитр|video|motion design/i },
];

function plain(value) {
  return String(value || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
}

const seen = new Set();
const matches = [];
for (const [index, item] of $input.all().entries()) {
  const post = item.json;
  const title = plain(post.title);
  const description = plain(post.contentSnippet || post.description || post.content);
  const demo = post.demo === true;
  const link = String(post.link || '').trim();
  const project = link.match(/^https?:\/\/(?:www\.)?fl\.ru\/projects\/(\d+)(?:[/?#]|$)/i);
  if (!demo && !project) continue;
  const key = demo ? 'demo:' + title : project[1];
  if (!title || seen.has(key)) continue;
  const headings = topics.filter(topic => topic.match.test(title));
  const found = headings.length ? headings : topics.filter(topic => topic.match.test(description));
  if (!found.length) continue;
  seen.add(key);

  const badge = title.match(/\(([^()]*)\)\s*$/)?.[1] || '';
  const free = /(?:^|,)\s*для всех\s*(?:,|$)/i.test(badge);
  const advertisedBudget = title.match(/бюджет\s*:\s*([^,;)]+)/i)?.[1]?.trim() || null;
  const date = Date.parse(post.isoDate || post.pubDate || '');
  matches.push({
    free, titleMatch: headings.length > 0, time: Number.isFinite(date) ? date : 0, index,
    card: {
      источник: demo ? 'Учебный пример' : 'Лента FL.ru',
      заказ: title, направления: found.map(topic => topic.name),
      бюджет_клиента: advertisedBudget,
      отклик: free ? 'В заголовке есть отметка «для всех»' : 'Стоимость уточняется в карточке заказа',
      детали: description.slice(0, 800),
      ссылка: demo ? null : link,
      опубликовано: Number.isFinite(date) ? new Date(date).toISOString() : null,
    },
  });
}
matches.sort((a, b) => Number(b.free) - Number(a.free)
  || Number(b.titleMatch) - Number(a.titleMatch) || b.time - a.time);
if (!matches.length) return [{ json: { результат: 'В этой выборке совпадений по навыкам нет.' } }];
return matches.map(match => ({ json: match.card, pairedItem: { item: match.index } }));
